def isbn_valid(s: str) -> bool:
    if not isinstance(s, str):
        return False

    isbn = s.replace("-", "").replace(" ", "")

    if len(isbn) == 10:
        if any(c not in "0123456789" for c in isbn[:9]):
            return False
        if isbn[9] not in "0123456789X":
            return False

        digits = [int(c) for c in isbn[:9]]
        digits.append(10 if isbn[9] == "X" else int(isbn[9]))
        return sum((i + 1) * digit for i, digit in enumerate(digits)) % 11 == 0

    if len(isbn) == 13:
        if any(c not in "0123456789" for c in isbn):
            return False

        return sum(
            int(digit) * (1 if i % 2 == 0 else 3)
            for i, digit in enumerate(isbn)
        ) % 10 == 0

    return False
